/** Insere as entradas da semente que ainda não existem (por chave e língua); nunca altera as existentes. */
export async function seedAssistant(db: Db) {
  const rows: unknown[][] = [];
  const order: Record<string, number> = {};
  for (const e of FAQ_SEED) {
    const sort = (order[e.audience] = (order[e.audience] ?? 0) + 10) + (e.audience === 'all' ? 900 : 0);
    for (const lang of ['pt', 'en'] as const) { const [q, a, k] = e[lang]; rows.push([e.key, lang, e.audience, q, a, k, sort]); }
  }
  const values = rows.map((_, i) => `($${i * 7 + 1},$${i * 7 + 2},$${i * 7 + 3},$${i * 7 + 4},$${i * 7 + 5},$${i * 7 + 6},$${i * 7 + 7})`).join(',');
  await db.query(`INSERT INTO assistant_faq(seed_key, lang, audience, question, answer, keywords, sort) VALUES ${values} ON CONFLICT (seed_key, lang) DO NOTHING`, rows.flat());
}
